use axum::{
    extract::{Path, Query, Json},
    routing::{get, post},
    Router,
    http::StatusCode,
    response::IntoResponse,
};
use serde::{Deserialize, Serialize};

// 1. هياكل البيانات للـ Requests والـ Responses
#[derive(Deserialize)]
struct Pagination {
    page: Option<usize>,
    limit: Option<usize>,
}

#[derive(Deserialize)]
struct CreateUserRequest {
    username: String,
    email: String,
}

#[derive(Serialize)]
struct UserResponse {
    id: u64,
    username: String,
    email: String,
}

// 2. Handlers
async fn list_users(Query(pagination): Query<Pagination>) -> impl IntoResponse {
    let page = pagination.page.unwrap_or(1);
    let limit = pagination.limit.unwrap_or(20);
    Json(format!("قائمة المستخدمين - صفحة {} بحجم {}", page, limit))
}

async fn create_user(
    Json(payload): Json<CreateUserRequest>,
) -> (StatusCode, Json<UserResponse>) {
    let new_user = UserResponse {
        id: 101,
        username: payload.username,
        email: payload.email,
    };
    (StatusCode::CREATED, Json(new_user))
}

async fn get_user_by_id(Path(user_id): Path<u64>) -> Result<Json<UserResponse>, StatusCode> {
    if user_id == 404 {
        return Err(StatusCode::NOT_FOUND);
    }
    Ok(Json(UserResponse {
        id: user_id,
        username: String::from("ahmed_dev"),
        email: String::from("ahmed@example.com"),
    }))
}

// 3. تركيب الـ Router وتشغيل السيرفر
#[tokio::main]
async fn main() {
    let app = Router::new()
        .route("/users", get(list_users).post(create_user))
        .route("/users/{id}", get(get_user_by_id));

    let listener = tokio::net::TcpListener::bind("0.0.0.0:3000").await.unwrap();
    println!("🚀 سيرفر Axum شغال على http://localhost:3000");
    axum::serve(listener, app).await.unwrap();
}

