use argon2::{
    password_hash::{
        rand_core::OsRng,
        PasswordHash, PasswordHasher, PasswordVerifier, SaltString
    },
    Argon2
};

// 1. دالة لتشفير كلمة المرور وتوليد Salt عشوائي آمن:
pub fn hash_password(password: &str) -> Result<String, String> {
    let salt = SaltString::generate(&mut OsRng);
    let argon2 = Argon2::default();

    argon2
        .hash_password(password.as_bytes(), &salt)
        .map(|hash| hash.to_string())
        .map_err(|e| format!("فشل التشفير: {}", e))
}

// 2. دالة لمطابقة كلمة المرور المدخلة مع الهاش المخزن في قاعدة البيانات:
pub fn verify_password(password: &str, password_hash: &str) -> Result<bool, String> {
    let parsed_hash = PasswordHash::new(password_hash)
        .map_err(|e| format!("تنسيق الهاش غير سليم: {}", e))?;

    let argon2 = Argon2::default();

    match argon2.verify_password(password.as_bytes(), &parsed_hash) {
        Ok(_) => Ok(true),
        Err(argon2::password_hash::Error::Password) => Ok(false), // كلمة المرور غير مطابقة
        Err(e) => Err(format!("خطأ أثناء التحقق: {}", e)),
    }
}

fn main() {
    let raw_password = "P@ssw0rd_Super_Secret_2026";

    // عملية التشفير:
    let hashed = hash_password(raw_password).unwrap();
    println!("الهاش المخزن بأمان: {}", hashed);

    // عملية تسجيل الدخول الصحيحة:
    let is_valid = verify_password(raw_password, &hashed).unwrap();
    println!("تسجيل الدخول صحيح: {}", is_valid); // true

    // محاولة اختراق بكلمة مرور خاطئة:
    let is_hacked = verify_password("wrong_password", &hashed).unwrap();
    println!("تسجيل دخول خاطئ: {}", is_hacked); // false
}
